import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In an increasing sequence of four positive integers a<b<c<d, the first three terms form an arithmetic progression, the last three terms form a geometric progression, the difference between the first and fourth terms equals {delta}, and the ratio (a+d):(b+c) equals {q_num}:{q_den}. Find the sum of the four terms.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We parametrize solutions by integers k>=2 and L>=2.
# For such k,L, the unique sequence is:
# a = k(k+1)L, b = (k+1)^2 L, c = (k+1)(k+2)L, d = (k+2)^2 L.
# Then b,c,d are GP with ratio (k+2)/(k+1), and a,b,c are AP with common difference (k+1)L.
# The difference delta = d - a = L(3k+4).
# The ratio (a+d)/(b+c) simplifies to Q = 1 + 1/m where m = (k+1)(2k+3).
# We output q_num = m+1 and q_den = m.
for _ in range(1000):
    k = rng.randint(2, 40)
    L = rng.randint(2, 30)
    m = (k+1)*(2*k+3)
    q_den = m
    q_num = m + 1
    delta = L*(3*k+4)
    # Keep numbers moderate; optional cap to avoid huge parameters
    if q_den <= 10**6 and delta <= 10**6:
        return {'delta': delta, 'q_num': q_num, 'q_den': q_den}
# Fallback with deterministic but valid small values if retries failed
k = 3
L = 2
m = (k+1)*(2*k+3)
return {'delta': L*(3*k+4), 'q_num': m+1, 'q_den': m}

    def verifier(assign):
# Validate and reconstruct the unique solution; enforce nontrivial structure.
try:
    delta = int(assign['delta'])
    q_num = int(assign['q_num'])
    q_den = int(assign['q_den'])
except Exception:
    # Missing or non-integer inputs
    return (False, None)
# Basic domain checks
if delta <= 0 or q_num <= 0 or q_den <= 0:
    # All must be positive integers
    return (False, None)
if q_num <= q_den:
    # Ratio must exceed 1
    return (False, None)
# We expect (a+d)/(b+c) = (m+1)/m with m integer.
# So q_num/q_den must equal 1 + 1/m -> m = q_den / (q_num - q_den)
diff = q_num - q_den
if q_den % diff != 0:
    # Not of the form 1 + 1/m
    return (False, None)
m = q_den // diff
# Solve (k+1)(2k+3) = m for integer k>=1.
import math
discr = 1 + 8*m
s = math.isqrt(discr)
if s*s != discr:
    # Discriminant not a perfect square
    return (False, None)
# s must equal 4k+5 for some integer k
if (s - 5) % 4 != 0:
    return (False, None)
k = (s - 5) // 4
if k < 1:
    return (False, None)
# Now L from delta = L(3k+4)
denom = 3*k + 4
if delta % denom != 0:
    # L must be integer
    return (False, None)
L = delta // denom
if L < 1:
    return (False, None)
# Construct the sequence
a = k*(k+1)*L
b = (k+1)*(k+1)*L
c = (k+1)*(k+2)*L
d = (k+2)*(k+2)*L
# Check increasing
if not (a < b < c < d):
    return (False, None)
# Check AP condition on first three
if not (b - a == c - b and b - a > 0):
    return (False, None)
# Check GP condition on last three: c^2 = b*d
if c*c != b*d:
    return (False, None)
# Check delta matches
if d - a != delta:
    return (False, None)
# Check ratio (a+d)/(b+c) matches q_num/q_den by cross-multiplication
if (a + d) * q_den != (b + c) * q_num:
    return (False, None)
# Compute the answer: sum of the four terms
answer = a + b + c + d
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

